import subprocess
import os
import shutil
from glob import glob
def task_func(src_folder, dst_folder):
    """
    Compress all files in the specified source folder using gzip and move the compressed files to a destination folder as a background process.

    Parameters:
    - src_folder (str): The source folder containing files to compress.
    - dst_folder (str): The destination folder for the compressed files.

    Returns:
    - dict: A dictionary containing:
        - 'success': Boolean indicating if all files were compressed and moved successfully.
        - 'message': A descriptive message about the operation's result.
        - 'failed_files': List of filenames that failed to compress or move.
    """
    if not os.path.exists(src_folder):
        return {
            'success': False,
            'message': f"Source folder '{src_folder}' does not exist.",
            'failed_files': []
        }
    if not os.path.exists(dst_folder):
        try:
            os.makedirs(dst_folder, exist_ok=True)
        except Exception as e:
            return {
                'success': False,
                'message': f"Failed to create destination folder '{dst_folder}': {e}",
                'failed_files': []
            }
    files = glob(os.path.join(src_folder, '*'))
    if not files:
        return {
            'success': True,
            'message': f"No files found in source folder '{src_folder}'.",
            'failed_files': []
        }
    failed_files = []
    successful_files = []
    for file_path in files:
        if os.path.isdir(file_path):
            continue
        try:
            # Compress the file in the background
            process = subprocess.Popen(['gzip', '-f', file_path], stdout=subprocess.PIPE, stderr=subprocess.PIPE)
            stdout, stderr = process.communicate()
            if process.returncode != 0:
                failed_files.append(os.path.basename(file_path))
                continue
            # The compressed file will have .gz extension
            compressed_file = file_path + '.gz'
            if os.path.exists(compressed_file):
                shutil.move(compressed_file, os.path.join(dst_folder, os.path.basename(compressed_file)))
                successful_files.append(os.path.basename(file_path))
            else:
                failed_files.append(os.path.basename(file_path))
        except Exception as e:
            failed_files.append(os.path.basename(file_path))
    success = len(failed_files) == 0
    message = f"Successfully compressed and moved {len(successful_files)} files." if success else f"Compressed and moved {len(successful_files)} files, {len(failed_files)} files failed."
    return {
        'success': success,
        'message': message,
        'failed_files': failed_files
    }
